//! Brand tray pixmaps, embedded once at compile time (no decoding, no allocation at runtime).
//! The `.argb` files are generated by `cargo xtask brand`; never edit them by hand.
//! Spec: docs/specs/ui/status-and-notifications.md §Desktop tray and menu bar.

use super::TrayIcon;

/// The installed app icon name (nfpm puts it in hicolor 256); used by notifications.
pub const APP_ICON_NAME: &str = "io.github.danielesc0911.lemusync";

macro_rules! pixmaps {
    ($name:literal) => {
        [
            (
                24,
                &include_bytes!(concat!("../../assets/tray/", $name, "-24.argb"))[..],
            ),
            (
                32,
                &include_bytes!(concat!("../../assets/tray/", $name, "-32.argb"))[..],
            ),
            (
                48,
                &include_bytes!(concat!("../../assets/tray/", $name, "-48.argb"))[..],
            ),
        ]
    };
}

impl TrayIcon {
    /// `(size in px, ARGB32 big-endian bytes)` at 24, 32 and 48 px, the `StatusNotifierItem` layout.
    #[must_use]
    pub fn pixmaps(self) -> [(i32, &'static [u8]); 3] {
        match self {
            Self::Synced => pixmaps!("synced"),
            Self::Syncing => pixmaps!("syncing"),
            Self::Paused => pixmaps!("paused"),
            Self::Offline => pixmaps!("offline"),
            Self::Attention => pixmaps!("attention"),
            Self::Error => pixmaps!("error"),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const ALL: [TrayIcon; 6] = [
        TrayIcon::Synced,
        TrayIcon::Syncing,
        TrayIcon::Paused,
        TrayIcon::Offline,
        TrayIcon::Attention,
        TrayIcon::Error,
    ];

    #[test]
    fn every_icon_has_three_sized_pixmaps() {
        for icon in ALL {
            let p = icon.pixmaps();
            for ((size, bytes), want) in p.iter().zip([24i32, 32, 48]) {
                assert_eq!(*size, want);
                assert_eq!(
                    bytes.len(),
                    4 * usize::try_from(want * want).unwrap(),
                    "{icon:?} {want}"
                );
            }
        }
    }

    #[test]
    fn states_look_different() {
        assert_ne!(
            TrayIcon::Synced.pixmaps()[0].1,
            TrayIcon::Error.pixmaps()[0].1
        );
    }

    #[test]
    fn notification_icon_is_the_app_icon() {
        assert_eq!(APP_ICON_NAME, "io.github.danielesc0911.lemusync");
    }
}
